1	//! This module contains logic for checking if any [`Reference`]s to a
2	//! [`Symbol`] are considered a usage.
3	
4	use itertools::Itertools;
5	use oxc_ast::{AstKind, ast::*};
6	use oxc_semantic::{AstNode, NodeId, Reference, ScopeId, SymbolFlags, SymbolId};
7	use oxc_span::{GetSpan, Span};
8	
9	use super::{NoUnusedVars, Symbol, ignored::FoundStatus};
10	
11	impl<'a> Symbol<'_, 'a> {
12	    // =========================================================================
13	    // ==================== ENABLE/DISABLE USAGE SUB-CHECKS ====================
14	    // =========================================================================
15	
16	    // NOTE(@don): all of these should be `#[inline]` and `const`. by inlining
17	    // it, rustc should be able to detect redundant flag checks and optimize
18	    // them away. Note that I haven't actually checked the assembly output to
19	    // confirm this; if you are reading this and decide to do so, please let me
20	    // know the results.
21	
22	    /// 1. Imported functions will never have calls to themselves within their
23	    ///    own declaration since they are declared outside the current module
24	    /// 2. Catch variables are always parameter-like and will therefore never have
25	    ///    a function declaration.
26	    #[inline]
27	    fn is_maybe_callable(&self) -> bool {
28	        // NOTE: imports are technically callable, but that call will never
29	        // occur within its own declaration since it's declared in another
30	        // module.
31	        const IMPORT: SymbolFlags = SymbolFlags::Import.union(SymbolFlags::TypeImport);
32	        // note: intetionally do not use `SymbolFlags::is_type` here, since that
33	        // can return `true` for values
34	        const TYPE: SymbolFlags =
35	            SymbolFlags::TypeAlias.union(SymbolFlags::TypeParameter).union(SymbolFlags::Interface);
36	        const ENUM: SymbolFlags = SymbolFlags::Enum.union(SymbolFlags::EnumMember);
37	        const NAMESPACE_LIKE: SymbolFlags =
38	            SymbolFlags::NamespaceModule.union(SymbolFlags::ValueModule);
39	
40	        !self.flags().intersects(
41	            IMPORT.union(TYPE).union(ENUM).union(NAMESPACE_LIKE).union(SymbolFlags::CatchVariable),
42	        )
43	    }
44	
45	    /// Note: we still need to check for reassignments to const variables since
46	    /// eslint's original rule requires it. Const reassignments are not a syntax
47	    /// error in JavaScript, only TypeScript.
48	    #[inline]
49	    fn is_possibly_reassignable(&self) -> bool {
50	        self.flags().is_variable()
51	    }
52	
53	    /// Check if this [`Symbol`] is definitely reassignable.
54	    ///
55	    /// Examples of non-reassignable symbols are:
56	    /// - function declarations
57	    /// - classes
58	    /// - enums
59	    /// - types (interfaces, type aliases)
60	    /// - const variables
61	    /// - imports
62	    ///
63	    /// Examples of reassinable symbols are:
64	    /// - `var` and `let` variable declarations
65	    /// - function parameters
66	    #[inline]
67	    fn is_definitely_reassignable_variable(&self) -> bool {
68	        let f = self.flags();
69	        f.is_variable() && !f.contains(SymbolFlags::ConstVariable.union(SymbolFlags::Function))
70	    }
71	
72	    /// Checks if this [`Symbol`] could be used as a type reference within its
73	    /// own declaration.
74	    ///
75	    /// This does _not_ imply this symbol is a type (negative cases include type
76	    /// imports, type parameters, etc).
77	    #[inline]
78	    fn could_have_type_reference_within_own_decl(&self) -> bool {
79	        #[rustfmt::skip]
80	        const TYPE_DECLS: SymbolFlags = SymbolFlags::TypeAlias
81	            .union(SymbolFlags::Interface)
82	            .union(SymbolFlags::Class);
83	
84	        self.flags().intersects(TYPE_DECLS)
85	    }
86	
87	    // =========================================================================
88	    // ============================= USAGE CHECKS ==============================
89	    // =========================================================================
90	
91	    /// Check if this [`Symbol`] has any [`Reference`]s that are considered a usage.
92	    pub fn has_usages(&self, options: &NoUnusedVars) -> bool {
93	        if self.is_function_or_class_declaration_used() {
94	            return true;
95	        }
96	
97	        // Use symbol flags to skip the usage checks we are certain don't need
98	        // to be run.
99	        let do_reassignment_checks = self.is_possibly_reassignable();
100	        let do_type_self_usage_checks = self.could_have_type_reference_within_own_decl();
101	        let do_self_call_check = self.is_maybe_callable();
102	        let do_discarded_read_checks = self.is_definitely_reassignable_variable();
103	
104	        for reference in self.references() {
105	            // Resolved references should always contain the id of the symbol
106	            // they are referencing. By making this an assertion instead of a
107	            // debug assertion, the rust compiler can optimize away None checks
108	            // performed down the line.
109	            assert!(
110	                reference.symbol_id().is_some(),
111	                "Resolved reference to symbol {:?} is missing a symbol id",
112	                self.id()
113	            );
114	            assert!(reference.symbol_id().is_some_and(|id| id == self.id()));
115	
116	            // ====================== Write usage checks =======================
117	
118	            if reference.is_write() {
119	                if do_reassignment_checks
120	                    && (self.is_assigned_to_ignored_destructure(reference, options)
121	                        || self.is_used_in_for_of_loop(reference))
122	                {
123	                    return true;
124	                }
125	
126	                // references can be both reads & writes. If this is only a
127	                // write, we don't need to perform any read usage checks.
128	                if !reference.is_read() {
129	                    continue;
130	                }
131	            }
132	
133	            // ======================= Type usage checks =======================
134	
135	            if reference.is_type() {
136	                // e.g. `type Foo = Array<Foo>`
137	                if do_type_self_usage_checks && self.is_type_self_usage(reference) {
138	                    continue;
139	                }
140	
141	                // ```ts
142	                // const foo = 123;
143	                // export type Foo = typeof foo
144	                // ```
145	                if options.report_vars_only_used_as_types
146	                    && !self.flags().intersects(SymbolFlags::TypeImport.union(SymbolFlags::Import))
147	                    && self.reference_contains_type_query(reference)
148	                {
149	                    continue;
150	                }
151	                // ```
152	                // function foo(): foo { }
153	                // ```
154	                if self
155	                    .get_ref_relevant_node(reference)
156	                    .is_some_and(|node| self.declaration().span().contains_inclusive(node.span()))
157	                {
158	                    continue;
159	                }
160	
161	                return true;
162	            }
163	
164	            // ======================= Read usage checks =======================
165	
166	            // e.g. `let a = 0; a = a + 1`
167	            if do_reassignment_checks && self.is_self_reassignment(reference) {
168	                continue;
169	            }
170	
171	            // e.g. reference on `a` in expression `let a = 0; let b = (a++, 0);`
172	            if do_discarded_read_checks && self.is_discarded_read(reference) {
173	                continue;
174	            }
175	
