1	use std::fmt;
2	
3	use cow_utils::CowUtils;
4	use oxc_diagnostics::OxcDiagnostic;
5	use oxc_semantic::SymbolFlags;
6	use oxc_span::{GetSpan, Span};
7	
8	use super::{Symbol, options::IgnorePattern};
9	
10	fn pronoun_for_symbol(
11	    symbol_flags: SymbolFlags,
12	) -> (/* singular */ &'static str, /* plural */ &'static str) {
13	    if symbol_flags.is_function() {
14	        ("Function", "functions")
15	    } else if symbol_flags.is_class() {
16	        ("Class", "classes")
17	    } else if symbol_flags.is_interface() {
18	        ("Interface", "interfaces")
19	    } else if symbol_flags.is_type_alias() {
20	        ("Type alias", "type aliases")
21	    } else if symbol_flags.is_enum() {
22	        ("Enum", "enums")
23	    } else if symbol_flags.is_enum_member() {
24	        ("Enum member", "enum members")
25	    } else if symbol_flags.is_type_import() {
26	        ("Type", "types")
27	    } else if symbol_flags.is_import() {
28	        ("Identifier", "identifiers")
29	    } else if symbol_flags.is_catch_variable() {
30	        ("Catch parameter", "caught errors")
31	    } else {
32	        ("Variable", "variables")
33	    }
34	}
35	
36	pub fn used_ignored<R>(symbol: &Symbol<'_, '_>, pat: &IgnorePattern<R>) -> OxcDiagnostic
37	where
38	    R: fmt::Display,
39	{
40	    let (pronoun_singular, _) = pronoun_for_symbol(symbol.flags());
41	    let name = symbol.name();
42	
43	    let help_suffix = match pat {
44	        IgnorePattern::None => ".".into(),
45	        IgnorePattern::Default => {
46	            name.strip_prefix('_').map_or(".".into(), |name| format!(" to '{name}'."))
47	        }
48	        IgnorePattern::Some(r) => {
49	            format!(" to match the pattern /{r}/.")
50	        }
51	    };
52	
53	    OxcDiagnostic::warn(format!("{pronoun_singular} '{name}' is marked as ignored but is used."))
54	        .with_label(symbol.span().label(format!("'{name}' is declared here")))
55	        .with_help(format!(
56	            "Consider renaming this {}{help_suffix}",
57	            pronoun_singular.cow_to_ascii_lowercase()
58	        ))
59	}
60	
61	/// Variable 'x' is declared but never used.
62	pub fn declared<R>(
63	    symbol: &Symbol<'_, '_>,
64	    pat: &IgnorePattern<R>,
65	    only_used_as_type: bool,
66	) -> OxcDiagnostic
67	where
68	    R: fmt::Display,
69	{
70	    let (verb, help) = if symbol.flags().is_catch_variable() {
71	        ("caught", "Consider handling this error.")
72	    } else {
73	        ("declared", "Consider removing this declaration.")
74	    };
75	    let name = symbol.name();
76	    let (pronoun, pronoun_plural) = pronoun_for_symbol(symbol.flags());
77	    let suffix = pat.diagnostic_help(pronoun_plural);
78	
79	    OxcDiagnostic::warn(if only_used_as_type {
80	        format!("{pronoun} is {verb} but only used as a type.{suffix}")
81	    } else {
82	        format!("{pronoun} '{name}' is {verb} but never used.{suffix}")
83	    })
84	    .with_label(symbol.span().label(format!("'{name}' is declared here")))
85	    .with_help(help)
86	}
87	
88	/// Variable 'x' is assigned a value but never used.
89	pub fn assign<R>(
90	    symbol: &Symbol<'_, '_>,
91	    assign_span: Span,
92	    pat: &IgnorePattern<R>,
93	) -> OxcDiagnostic
94	where
95	    R: fmt::Display,
96	{
97	    let name = symbol.name();
98	    let (pronoun, pronoun_plural) = pronoun_for_symbol(symbol.flags());
99	    let suffix = pat.diagnostic_help(pronoun_plural);
100	
101	    OxcDiagnostic::warn(format!("{pronoun} '{name}' is assigned a value but never used.{suffix}"))
102	        .with_labels([
103	            symbol.span().label(format!("'{name}' is declared here")),
104	            assign_span.label("it was last assigned here"),
105	        ])
106	        .with_help("Did you mean to use this variable?")
107	}
108	
109	/// Parameter 'x' is declared but never used.
110	pub fn param<R>(
111	    symbol: &Symbol<'_, '_>,
112	    pat: &IgnorePattern<R>,
113	    only_used_as_type: bool,
114	) -> OxcDiagnostic
115	where
116	    R: fmt::Display,
117	{
118	    let name = symbol.name();
119	    let suffix = pat.diagnostic_help("parameters");
120	
121	    OxcDiagnostic::warn(if only_used_as_type {
122	        format!("Parameter '{name}' is declared but only used as a type.{suffix}")
123	    } else {
124	        format!("Parameter '{name}' is declared but never used.{suffix}")
125	    })
126	    .with_label(symbol.span().label(format!("'{name}' is declared here")))
127	    .with_help("Consider removing this parameter.")
128	}
129	
130	/// Identifier 'x' imported but never used.
131	pub fn imported(symbol: &Symbol<'_, '_>) -> OxcDiagnostic {
132	    let (pronoun, _) = pronoun_for_symbol(symbol.flags());
133	    let name = symbol.name();
134	
135	    OxcDiagnostic::warn(format!("{pronoun} '{name}' is imported but never used."))
136	        .with_label(symbol.span().label(format!("'{name}' is imported here")))
137	        .with_help("Consider removing this import.")
138	}
