3	//!
4	//! This example demonstrates how to create a basic linter using Oxc's parser and semantic analyzer.
5	//! It implements simple rules to detect debugger statements and empty destructuring patterns.
6	//!
7	//! ## Usage
8	//!
9	//! Create a `test.js` file and run:
10	//! ```bash
11	//! cargo run -p oxc_linter --example linter [filename]
12	//! ```
13	
14	use std::{env, path::Path};
15	
16	use oxc_allocator::Allocator;
17	use oxc_ast::AstKind;
18	use oxc_diagnostics::OxcDiagnostic;
19	use oxc_parser::Parser;
20	use oxc_semantic::SemanticBuilder;
21	use oxc_span::{SourceType, Span};
22	
23	// Instruction:
24	// create a `test.js`,
25	// run `cargo run -p oxc_linter --example linter`
26	// or `cargo watch -x "run -p oxc_linter --example linter"`
27	
28	/// Run a simple linter on a JavaScript file
29	fn main() -> std::io::Result<()> {
30	    let name = env::args().nth(1).unwrap_or_else(|| "test.js".to_string());
31	    let path = Path::new(&name);
32	    let source_text = std::fs::read_to_string(path)?;
33	    let allocator = Allocator::default();
34	    let source_type = SourceType::from_path(path).unwrap();
35	    let ret = Parser::new(&allocator, &source_text, source_type).parse();
36	
37	    // Handle parser errors
38	    if !ret.errors.is_empty() {
39	        print_errors(&source_text, ret.errors);
40	        return Ok(());
41	    }
42	
43	    // Build semantic model for AST analysis
44	    let semantic_ret = SemanticBuilder::new().build(&ret.program);
45	
46	    let mut errors: Vec<OxcDiagnostic> = vec![];
47	
48	    // Check for linting violations
49	    for node in semantic_ret.semantic.nodes() {
50	        match node.kind() {
51	            AstKind::DebuggerStatement(stmt) => {
52	                errors.push(no_debugger(stmt.span));
53	            }
54	            AstKind::ArrayPattern(array) if array.elements.is_empty() => {
55	                errors.push(no_empty_pattern("array", array.span));
56	            }
57	            AstKind::ObjectPattern(object) if object.properties.is_empty() => {
58	                errors.push(no_empty_pattern("object", object.span));
59	            }
60	            _ => {}
61	        }
62	    }
63	
64	    // Report results
65	    if errors.is_empty() {
66	        println!("Success!");
67	    } else {
68	        print_errors(&source_text, errors);
69	    }
70	
71	    Ok(())
72	}
